# Surah Al-Ahqaf (chapter 46) — part 3: ayat 25-35 (IDs 4535-4545)
SURAH = 46

ENTRIES = {
4535: (
"وہ ہر چیز کو اپنے رب کے حکم سے تباہ کر رہی تھی — پس وہ ایسے ہو گئے کہ ان کے گھروں کے سوا کچھ نہ دکھائی دیتا — اسی طرح ہم مجرموں کو بدلہ دیتے ہیں",
"""۱۔ تباہی — تدمر کل شیء بأمر ربها؛ فأصبحوا لا یُرى إلا مساکنهم؛ کذلک نجزي القوم المجرمین۔
۲۔ ’’تُدَمِّرُ كُلَّ شَيْءٍ بِأَمْرِ رَبِّهَا فَأَصْبَحُوا لَا يُرَىٰ إِلَّا مَسَاكِنُهُمْ كَذَٰلِكَ نَجْزِي الْقَوْمَ الْمُجْرِمِينَ‘‘ — وہ ہر چیز کو اپنے رب کے حکم سے تباہ کر رہی تھی — پس وہ ایسے ہو گئے کہ ان کے گھروں کے سوا کچھ نہ دکھائی دیتا — اسی طرح ہم مجرموں کو بدلہ دیتے ہیں — یعنی وہ ہر چیز کو اپنے رب کے حکم سے تباہ کر رہی تھی پس وہ ایسے ہو گئے کہ ان کے گھروں کے سوا کچھ نہ دکھائی دیتا اسی طرح ہم مجرموں کو بدلہ دیتے ہیں۔
۳۔ عملی سبق: مجرم قوم نہ بنو؛ اللہ سے ڈرو۔"""
),
4536: (
"اور ہم نے انہیں اس چیز میں اقتدار دیا جس میں ہم نے تمہیں اقتدار نہیں دیا — اور ہم نے انہیں کان آنکھیں اور دل دیے — پس انہیں ان کے کان ان کی آنکھیں اور ان کے دل کوئی فائدہ نہ دے سکے جب وہ اللہ کی آیات کا انکار کرتے تھے — اور انہیں وہ چیز آ گھیرتی تھی جس کا وہ مذاق اڑاتے تھے",
"""۱۔ قوتیں بے فائدہ — و لقد مکناهم فیما إن مکناکم فیه؛ و جعلنا لهم سمعًا و أبصارًا و أفئدة؛ فما أغنی عنهم سمعهم و لا أبصارهم و لا أفئدتهم من شیء؛ إذ کانوا یجحدون بآیات اللہ؛ و حاق بهم ما کانوا به یستهزئون۔
۲۔ ’’وَلَقَدْ مَكَّنَّاهُمْ فِيمَا إِن مَّكَّنَّاكُمْ فِيهِ وَجَعَلْنَا لَهُمْ سَمْعًا وَأَبْصَارًا وَأَفْئِدَۃً فَمَا أَغْنَىٰ عَنْهُمْ سَمْعُهُمْ وَلَا أَبْصَارُهُمْ وَلَا أَفْئِدَتُهُم مِّن شَيْءٍ إِذْ كَانُوا يَجْحَدُونَ بِآيَاتِ اللَّهِ وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ‘‘ — اور ہم نے انہیں اس چیز میں اقتدار دیا جس میں ہم نے تمہیں اقتدار نہیں دیا — اور ہم نے انہیں کان آنکھیں اور دل دیے — پس انہیں ان کے کان ان کی آنکھیں اور ان کے دل کوئی فائدہ نہ دے سکے جب وہ اللہ کی آیات کا انکار کرتے تھے — اور انہیں وہ چیز آ گھیرتی تھی جس کا وہ مذاق اڑاتے تھے — یعنی اور ہم نے انہیں اس چیز میں اقتدار دیا جس میں ہم نے تمہیں اقتدار نہیں دیا اور ہم نے انہیں کان آنکھیں اور دل دیے پس انہیں ان کے کان ان کی آنکھیں اور ان کے دل کوئی فائدہ نہ دے سکے جب وہ اللہ کی آیات کا انکار کرتے تھے اور انہیں وہ چیز آ گھیرتی تھی جس کا وہ مذاق اڑاتے تھے۔
۳۔ عملی سبق: اللہ کی آیات کا انکار نہ کرو؛ مذاق چھوڑو؛ اللہ سے ڈرو۔"""
),
4537: (
"اور ہم نے تمہارے اردگرد کی بستیوں کو ہلاک کر دیا — اور ہم نے آیات کو طرح طرح سے بیان کیا تاکہ وہ لوٹ آئیں",
"""۱۔ تباہ بستیاں — و لقد أهلکنا ما حولکم من القرى؛ و صرفنا الآیات لعلهم یرجعون۔
۲۔ ’’وَلَقَدْ أَهْلَكْنَا مَا حَوْلَكُم مِّنَ الْقُرَىٰ وَصَرَّفْنَا الْآيَاتِ لَعَلَّهُمْ يَرْجِعُونَ‘‘ — اور ہم نے تمہارے اردگرد کی بستیوں کو ہلاک کر دیا — اور ہم نے آیات کو طرح طرح سے بیان کیا تاکہ وہ لوٹ آئیں — یعنی اور ہم نے تمہارے اردگرد کی بستیوں کو ہلاک کر دیا اور ہم نے آیات کو طرح طرح سے بیان کیا تاکہ وہ لوٹ آئیں۔
۳۔ عملی سبق: گزشتہ بستیوں سے عبرت لو؛ اللہ سے لوٹو؛ اللہ سے ڈرو۔"""
),
4538: (
"پھر جنہیں انہوں نے اللہ کے سوا اللہ کا تقرب حاصل کرنے کے لیے معبود بنایا تھا ان کی مدد کیوں نہیں کی؟ — بلکہ وہ ان سے گم ہو گئے — اور یہ ان کی من گھڑت بات اور وہ جھوٹ تھا جو وہ گھڑتے تھے",
"""۱۔ معبود بے بس — فلولا نصرهم الذین اتخذوا من دون اللہ قربانًا آلهۃ؛ بل ضلوا عنهم؛ و ذلک إْفکهم و ما کانوا یفترون۔
۲۔ ’’فَلَوْلَا نَصَرَهُمُ الَّذِينَ اتَّخَذُوا مِن دُونِ اللَّهِ قُرْبَانًا آلِهَۃً بَل ضَلُّوا عَنْهُمْ وَذَٰلِكَ إِفْكُهُمْ وَمَا كَانُوا يَفْتَرُونَ‘‘ — پھر جنہیں انہوں نے اللہ کے سوا اللہ کا تقرب حاصل کرنے کے لیے معبود بنایا تھا ان کی مدد کیوں نہیں کی؟ — بلکہ وہ ان سے گم ہو گئے — اور یہ ان کی من گھڑت بات اور وہ جھوٹ تھا جو وہ گھڑتے تھے — یعنی پھر جنہیں انہوں نے اللہ کے سوا اللہ کا تقرب حاصل کرنے کے لیے معبود بنایا تھا ان کی مدد کیوں نہیں کی بلکہ وہ ان سے گم ہو گئے اور یہ ان کی من گھڑت بات اور وہ جھوٹ تھا جو وہ گھڑتے تھے۔
۳۔ عملی سبق: غیروں کو معبود نہ بناؤ؛ اللہ سے ڈرو۔"""
),
4539: (
"اور جب ہم نے جنات کی ایک جماعت کو تیری طرف متوجہ کیا تاکہ وہ قرآن سنیں — پس جب وہ اس کے پاس پہنچے تو انہوں نے کہا خاموش رہو — پھر جب قرآن پڑھ کر سنایا جا چکا تو وہ اپنی قوم کی طرف واپس لوٹے ڈرانے والے بن کر",
"""۱۔ جنات کا قرآن سننا — و إذ صرفنا إلیک نفرًا من الجن یستمعون القرآن؛ فلما حضروه قالوا أنصتوا؛ فلما قُضي ولّوا إلی قومهم منذرین۔
۲۔ ’’وَإِذْ صَرَفْنَا إِلَيْكَ نَفَرًا مِّنَ الْجِنِّ يَسْتَمِعُونَ الْقُرْآنَ فَلَمَّا حَضَرُوهُ قَالُوا أَنصِتُوا فَلَمَّا قُضِيَ وَلَّوْا إِلَىٰ قَوْمِهِم مُّنذِرِينَ‘‘ — اور جب ہم نے جنات کی ایک جماعت کو تیری طرف متوجہ کیا تاکہ وہ قرآن سنیں — پس جب وہ اس کے پاس پہنچے تو انہوں نے کہا خاموش رہو — پھر جب قرآن پڑھ کر سنایا جا چکا تو وہ اپنی قوم کی طرف واپس لوٹے ڈرانے والے بن کر — یعنی اور جب ہم نے جنات کی ایک جماعت کو تیری طرف متوجہ کیا تاکہ وہ قرآن سنیں پس جب وہ اس کے پاس پہنچے تو انہوں نے کہا خاموش رہو پھر جب قرآن پڑھ کر سنایا جا چکا تو وہ اپنی قوم کی طرف واپس لوٹے ڈرانے والے بن کر۔
۳۔ عملی سبق: قرآن کو توجہ سے سنو؛ اللہ سے ڈرو۔"""
),
4540: (
"انہوں نے کہا اے ہماری قوم بے شک ہم نے ایک کتاب سنی ہے جو موسیٰ کے بعد نازل کی گئی — اپنے سے پہلے کی تصدیق کرنے والی ہے — حق کی طرف اور سیدھے راستے کی طرف رہنمائی کرتی ہے",
"""۱۔ جنات کا اعتراف — قالوا یا قومنا إنا سمعنا کتابًا أنزل من بعد موسیٰ؛ مصدقًا لما بین یدیه؛ یهدي إلی الحق و إلی طریق مستقیم۔
۲۔ ’’قَالُوا يَا قَوْمَنَا إِنَّا سَمِعْنَا كِتَابًا أُنزِلَ مِن بَعْدِ مُوسَىٰ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ يَهْدِي إِلَى الْحَقِّ وَإِلَىٰ طَرِيقٍ مُّسْتَقِيمٍ‘‘ — انہوں نے کہا اے ہماری قوم بے شک ہم نے ایک کتاب سنی ہے جو موسیٰ کے بعد نازل کی گئی — اپنے سے پہلے کی تصدیق کرنے والی ہے — حق کی طرف اور سیدھے راستے کی طرف رہنمائی کرتی ہے — یعنی انہوں نے کہا اے ہماری قوم بے شک ہم نے ایک کتاب سنی ہے جو موسیٰ کے بعد نازل کی گئی اپنے سے پہلے کی تصدیق کرنے والی ہے حق کی طرف اور سیدھے راستے کی طرف رہنمائی کرتی ہے۔
۳۔ عملی سبق: جنات کی گواہی سے سبق لو؛ قرآن کی پیروی کرو؛ اللہ سے ڈرو۔"""
),
4541: (
"اے ہماری قوم اللہ کے بلانے والے کی بات مانو — اور اس پر ایمان لاؤ — وہ تمہارے گناہ معاف فرمائے گا — اور تمہیں دردناک عذاب سے پناہ دے گا",
"""۱۔ جنات کی دعوت — یا قومنا أجیبوا داعي اللہ و آمنوا به؛ یغفر لکم من ذنوبکم و یجرکم من عذاب ألیم۔
۲۔ ’’يَا قَوْمَنَا أَجِيبُوا دَاعِيَ اللَّهِ وَآمِنُوا بِهِ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍ‘‘ — اے ہماری قوم اللہ کے بلانے والے کی بات مانو — اور اس پر ایمان لاؤ — وہ تمہارے گناہ معاف فرمائے گا — اور تمہیں دردناک عذاب سے پناہ دے گا — یعنی اے ہماری قوم اللہ کے بلانے والے کی بات مانو اور اس پر ایمان لاؤ وہ تمہارے گناہ معاف فرمائے گا اور تمہیں دردناک عذاب سے پناہ دے گا۔
۳۔ عملی سبق: اللہ کے بلانے والے کو مانو؛ اللہ سے ڈرو۔"""
),
4542: (
"اور جو اللہ کے بلانے والے کی بات نہ مانے تو وہ زمین میں عاجز کرنے والا نہیں — اور نہ اس کے سوا اس کے لیے کوئی دوست ہیں — یہی لوگ واضح گمراہی میں ہیں",
"""۱۔ انکار کی سزا — و من لا یجب داعي اللہ فلیس بمعجز في الأرض؛ و لیس له من دونه أولیاء؛ أولئک في ضلال مبین۔
۲۔ ’’وَمَن لَّا يُجِبْ دَاعِيَ اللَّهِ فَلَيْسَ بِمُعْجِزٍ فِي الْأَرْضِ وَلَيْسَ لَهُ مِن دُونِهِ أَوْلِيَاءُ أُولَٰئِكَ فِي ضَلَالٍ مُّبِينٍ‘‘ — اور جو اللہ کے بلانے والے کی بات نہ مانے تو وہ زمین میں عاجز کرنے والا نہیں — اور نہ اس کے سوا اس کے لیے کوئی دوست ہیں — یہی لوگ واضح گمراہی میں ہیں — یعنی اور جو اللہ کے بلانے والے کی بات نہ مانے تو وہ زمین میں عاجز کرنے والا نہیں اور نہ اس کے سوا اس کے لیے کوئی دوست ہیں یہی لوگ واضح گمراہی میں ہیں۔
۳۔ عملی سبق: انکار سے بچو؛ اللہ سے ڈرو۔"""
),
4543: (
"کیا انہوں نے نہیں دیکھا کہ اللہ جس نے آسمان و زمین پیدا کیے اور انہیں پیدا کرنے سے عاجز نہیں ہوا — وہ مردوں کو زندہ کرنے پر قادر ہے — کیوں نہیں وہ تو ہر چیز پر قادر ہے",
"""۱۔ احیاء الموتٰی — أولم یروا أن اللہ الذی خلق السماوات والأرض و لم یع بخلقهن بقادر علی أن یحیي الموتیٰ؛ بلی إنه علی کل شیء قدیر۔
۲۔ ’’أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَلَمْ يَعْيَ بِخَلْقِهِنَّ بِقَادِرٍ عَلَىٰ أَن يُحْيِيَ الْمَوْتَىٰ بَلَىٰ إِنَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ‘‘ — کیا انہوں نے نہیں دیکھا کہ اللہ جس نے آسمان و زمین پیدا کیے اور انہیں پیدا کرنے سے عاجز نہیں ہوا — وہ مردوں کو زندہ کرنے پر قادر ہے — کیوں نہیں وہ تو ہر چیز پر قادر ہے — یعنی کیا انہوں نے نہیں دیکھا کہ اللہ جس نے آسمان و زمین پیدا کیے اور انہیں پیدا کرنے سے عاجز نہیں ہوا وہ مردوں کو زندہ کرنے پر قادر ہے کیوں نہیں وہ تو ہر چیز پر قادر ہے۔
۳۔ عملی سبق: قیامت پر ایمان رکھو؛ اللہ کی قدرت کا یقین کرو؛ اللہ سے ڈرو۔"""
),
4544: (
"اور جس دن کافر آگ پر پیش کیے جائیں گے — کیا یہ حق نہیں؟ — وہ کہیں گے کیوں نہیں ہمارے رب کی قسم — کہا جائے گا تو عذاب کا مزا چکھو اس کے بدلے کہ تم کفر کرتے تھے",
"""۱۔ آگ پر پیش — و یوم یعرض الذین کفروا علی النار؛ ألیس هذا بالحق؛ قالوا بلی و ربنا؛ قال فذوقوا العذاب بما کنتم تکفرون۔
۲۔ ’’وَيَوْمَ يُعْرَضُ الَّذِينَ كَفَرُوا عَلَى النَّارِ أَلَيْسَ هَٰذَا بِالْحَقِّ قَالُوا بَلَىٰ وَرَبِّنَا قَالَ فَذُوقُوا الْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ‘‘ — اور جس دن کافر آگ پر پیش کیے جائیں گے — کیا یہ حق نہیں؟ — وہ کہیں گے کیوں نہیں ہمارے رب کی قسم — کہا جائے گا تو عذاب کا مزا چکھو اس کے بدلے کہ تم کفر کرتے تھے — یعنی اور جس دن کافر آگ پر پیش کیے جائیں گے کیا یہ حق نہیں وہ کہیں گے کیوں نہیں ہمارے رب کی قسم کہا جائے گا تو عذاب کا مزا چکھو اس کے بدلے کہ تم کفر کرتے تھے۔
۳۔ عملی سبق: کفر سے بچو؛ عذاب سے ڈروسے بچو؛ خوفِ خدا اختیار کرو۔"""
),
4545: (
"پس صبر کرو جس طرح اولوالعزم رسولوں نے صبر کیا — اور ان کے لیے جلدی نہ کرو — جس دن وہ وہ دیکھیں گے جس کا ان سے وعدہ کیا جاتا ہے — (تو ایسے لگے گا) جیسے انہوں نے نہ گزارا ہو مگر دن کا ایک گھنٹہ — یہ پیغام پہنچا دینا ہے — تو کیا ہلاک ہوں گے سوائے فاسق قوم کے",
"""۱۔ صبر کی تلقین — فاصبر کم— ا صبر أولوا العزم من الرسل؛ و لا تستعجل لهم؛ کأنهم یوم یرون ما یوعدون لم یلبثوا إلا ساعة من نهار؛ بلاغ؛ فهل یهلک إلا القوم الفاسقون۔
۲۔ ’’فَاصْبِرْ كَمَا صَبَرَ أُولُو الْعَزْمِ مِنَ الرُّسُلِ وَلَا تَسْتَعْجِل لَّهُمْ كَأَنَّهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَ لَمْ يَلْبَثُوا إِلَّا سَاعَۃً مِّن نَّهَارٍ بَلَاغٌ فَهَلْ يُهْلَكُ إِلَّا الْقَوْمُ الْفَاسِقُونَ‘‘ — پس صبر کرو جس طرح اولوالعزم رسولوں نے صبر کیا — اور ان کے لیے جلدی نہ کرو — جس دن وہ وہ دیکھیں گے جس کا ان سے وعدہ کیا جاتا ہے — (تو ایسے لگے گا) جیسے انہوں نے نہ گزارا ہو مگر دن کا ایک گھنٹہ — یہ پیغام پہنچا دینا ہے — تو کیا ہلاک ہوں گے سوائے فاسق قوم کے — یعنی پس صبر کرو جس طرح اولوالعزم رسولوں نے صبر کیا اور ان کے لیے جلدی نہ کرو جس دن وہ وہ دیکھیں گے جس کا ان سے وعدہ کیا جاتا ہے (تو ایسے لگے گا) جیسے انہوں نے نہ گزارا ہو مگر دن کا ایک گھنٹہ یہ پیغام پہنچا دینا ہے تو کیا ہلاک ہوں گے سوائے فاسق قوم کے۔
۳۔ عملی سبق: صبر اختیار کرو؛ نبی ﷺ کی پیروی کرو؛ اللہ سے ڈرو۔"""
),
}
